// InvoicePosition is a place in an organization's invoice order: an invoice's creation time and ID.
type InvoicePosition struct {
	CreatedAt time.Time
	ID        string
}

// ListInvoices returns an organization's invoices that match f, oldest first (ties by ID).
func (s *Store) ListInvoices(orgID string, f InvoiceFilter) []Invoice {
	invs, _ := s.ListInvoicesAfter(orgID, f, nil, math.MaxInt)
	return invs
}

// ListInvoicesAfter returns up to limit of an organization's invoices that match f, oldest first (ties by ID), starting
// after the position after, or from the oldest when after is nil. more reports whether a matching invoice follows the
// last one returned.
func (s *Store) ListInvoicesAfter(orgID string, f InvoiceFilter, after *InvoicePosition, limit int) (invs []Invoice, more bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	ids := s.invoiceOrder[orgID]
	start := 0
	if after != nil {
		start = sort.Search(len(ids), func(i int) bool {
			inv := s.invoices[ids[i]]
			return keyLess(after.CreatedAt, after.ID, inv.CreatedAt, inv.ID)
		})
	}
	out := []Invoice{}
	for _, id := range ids[start:] {
		inv := s.invoices[id]
		if (f.CustomerID != "" && inv.CustomerID != f.CustomerID) || (f.SubscriptionID != "" && inv.SubscriptionID != f.SubscriptionID) || (f.Status != "" && inv.Status != f.Status) {
			continue
		}
		if len(out) == limit {
			return out, true
		}
		out = append(out, copyInvoice(inv))
	}
	return out, false
}

// indexInvoice adds a stored invoice to its organization's listing order. The caller holds the lock.
func (s *Store) indexInvoice(inv Invoice) {
	ids := s.invoiceOrder[inv.OrgID]
	i := sort.Search(len(ids), func(i int) bool {
		other := s.invoices[ids[i]]
		return keyLess(inv.CreatedAt, inv.ID, other.CreatedAt, other.ID)
	})
	s.invoiceOrder[inv.OrgID] = slices.Insert(ids, i, inv.ID)
}

// keyLess orders invoices by creation time, then ID.
func keyLess(t1 time.Time, id1 string, t2 time.Time, id2 string) bool {
	if !t1.Equal(t2) {
		return t1.Before(t2)
	}
	return id1 < id2
}

