// TestInvoiceListingWhileCreating pages through the listing while invoices are created between pages. The walk must
// return every invoice that existed before it, in order, and the new ones after them, each exactly once.
func TestInvoiceListingWhileCreating(t *testing.T) {
	e := apitest.New(t)
	cs := seedCustomers(t, e, e.Acme, 4)
	e.Clock.Set(apitest.Start.Add(time.Hour))
	seedInvoices(t, e, e.Acme, cs, 30, func(i int) time.Time { return apitest.Start.Add(time.Duration(i/3) * time.Minute) })
	var before []string
	for _, inv := range e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{}) {
		before = append(before, inv.ID)
	}

	var seen []string
	created := map[string]bool{}
	for cur := ""; ; {
		path := "/v1/invoices?limit=4"
		if cur != "" {
			path += "&cursor=" + cur
		}
		var p invoicePage
		e.MustDo(http.StatusOK, "GET", path, e.Acme.Key, nil, &p)
		for _, raw := range p.Items {
			seen = append(seen, refOf(t, raw).ID)
		}
		if p.NextCursor == "" {
			break
		}
		cur = p.NextCursor
		e.Clock.Advance(time.Minute)
		r := e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{
			"customer_id": cs[0].ID, "currency": "USD", "lines": []map[string]any{{"description": "Late", "quantity": 1, "unit_amount": 500}},
		}, nil)
		created[refOf(t, r.Body).ID] = true
	}

	if len(seen) != len(before)+len(created) {
		t.Fatalf("the walk gave %d invoices, want %d existing and %d created", len(seen), len(before), len(created))
	}
	for i, id := range seen {
		if i < len(before) && id != before[i] {
			t.Fatalf("item %d is %s, want %s", i, id, before[i])
		}
		if i >= len(before) && !created[id] {
			t.Fatalf("item %d is %s, which was not created during the walk", i, id)
		}
	}
	if len(created) == 0 {
		t.Fatal("no invoice was created between pages")
	}
}

// TestInvoiceListingLargeOrganization times the listing for an organization with 60,000 invoices and 5,000 customers,
// with another organization's invoices in the store too. Every request must answer within the 250 ms budget.
func TestInvoiceListingLargeOrganization(t *testing.T) {
	e := apitest.New(t)
	acme := seedCustomers(t, e, e.Acme, 5000)
	globex := seedCustomers(t, e, e.Globex, 50)
