	const budget = 250 * time.Millisecond
	queries := []string{
		"limit=20",
		"customer_id=" + acme[42].ID,
		"subscription_id=sub_2",
		"status=open",
		"status=void&customer_id=" + acme[7].ID,
		"customer_id=" + globex[1].ID,
	}
	for _, q := range queries {
		start := time.Now()
		r := e.Do("GET", "/v1/invoices?"+q, e.Acme.Key, nil)
