func TestInvoiceListingPages(t *testing.T) {
	e := apitest.New(t)
	acme := seedCustomers(t, e, e.Acme, 12)
	globex := seedCustomers(t, e, e.Globex, 3)
	// Creation times run out of order and repeat, so the order and the ties by ID are both exercised.
	seedInvoices(t, e, e.Acme, acme, 60, func(i int) time.Time { return apitest.Start.Add(time.Duration(i*7%23) * time.Minute) })
	seedInvoices(t, e, e.Globex, globex, 25, func(i int) time.Time { return apitest.Start.Add(time.Duration(i%4) * time.Minute) })
	// The invoices of a deleted customer still list, with a null customer.
	if err := e.Store.DeleteCustomer(e.Acme.ID, acme[3].ID); err != nil {
		t.Fatal(err)
	}

	cases := []struct {
		query  string
		filter store.InvoiceFilter
	}{
		{"", store.InvoiceFilter{}},
		{"customer_id=" + acme[0].ID, store.InvoiceFilter{CustomerID: acme[0].ID}},
		{"customer_id=" + acme[3].ID, store.InvoiceFilter{CustomerID: acme[3].ID}},
		{"customer_id=" + globex[0].ID, store.InvoiceFilter{CustomerID: globex[0].ID}},
		{"subscription_id=sub_1", store.InvoiceFilter{SubscriptionID: "sub_1"}},
		{"status=open", store.InvoiceFilter{Status: store.InvoiceOpen}},
		{"status=paid", store.InvoiceFilter{Status: store.InvoicePaid}},
		{"status=void", store.InvoiceFilter{Status: store.InvoiceVoid}},
		{"status=void&customer_id=" + acme[1].ID + "&subscription_id=sub_2", store.InvoiceFilter{Status: store.InvoiceVoid, CustomerID: acme[1].ID, SubscriptionID: "sub_2"}},
