package api_test

import (
	"encoding/json"
	"fmt"
	"net/http"
	"reflect"
	"strings"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// invoicePage is one page of GET /v1/invoices, with each item left raw so it can be compared exactly.
type invoicePage struct {
	Items      []json.RawMessage `json:"items"`
	NextCursor string            `json:"next_cursor"`
}

// seedCustomers creates n customers in org.
func seedCustomers(t testing.TB, e *apitest.Env, org apitest.Org, n int) []store.Customer {
	t.Helper()
	cs := make([]store.Customer, 0, n)
	for i := 0; i < n; i++ {
		c, err := e.Store.CreateCustomer(org.ID, fmt.Sprintf("Customer %d", i), fmt.Sprintf("c%d@%s.example", i, strings.ToLower(org.Name)), apitest.Start)
		if err != nil {
			t.Fatal(err)
		}
		cs = append(cs, c)
	}
	return cs
}

// seedInvoices stores n invoices for org, cycling through the customers and three subscriptions, and pays or voids some of
// them. Invoice i is created at at(i).
func seedInvoices(t testing.TB, e *apitest.Env, org apitest.Org, customers []store.Customer, n int, at func(i int) time.Time) {
	t.Helper()
	subs := []string{"", "sub_1", "sub_2"}
	for i := 0; i < n; i++ {
		when := at(i)
		inv, err := e.Store.CreateInvoice(store.Invoice{
			OrgID: org.ID, CustomerID: customers[i%len(customers)].ID, SubscriptionID: subs[i%len(subs)], Currency: money.USD,
			Lines:           []store.Line{{Description: fmt.Sprintf("Item %d", i), Quantity: 1 + int64(i%3), UnitAmount: 100 + int64(i)}},
			DiscountPercent: (i % 4) * 5,
		}, when)
		if err != nil {
			t.Fatal(err)
		}
		if i%5 != 0 && i%7 != 0 {
			continue
		}
		if _, err := e.Store.UpdateInvoice(org.ID, inv.ID, func(x *store.Invoice) error {
			if i%5 == 0 {
				x.Status, x.PaidAt = store.InvoicePaid, &when
			} else {
				x.Status, x.VoidedAt = store.InvoiceVoid, &when
			}
			return nil
		}); err != nil {
			t.Fatal(err)
		}
	}
}

// walkInvoices follows next_cursor through GET /v1/invoices with the query and returns every item in order.
func walkInvoices(t testing.TB, e *apitest.Env, key, query string) []json.RawMessage {
	t.Helper()
	var all []json.RawMessage
	for cur := ""; ; {
		path := "/v1/invoices?" + query
		if cur != "" {
			path += "&cursor=" + cur
		}
		var p invoicePage
		e.MustDo(http.StatusOK, "GET", path, key, nil, &p)
		all = append(all, p.Items...)
		if p.NextCursor == "" {
			return all
		}
		cur = p.NextCursor
		if len(all) > 1_000_000 {
			t.Fatalf("%s: the cursor never ends", query)
		}
	}
}

// invoiceRef is the part of an invoice item that identifies it.
type invoiceRef struct {
	ID    string `json:"id"`
	OrgID string `json:"org_id"`
}

func refOf(t testing.TB, raw []byte) invoiceRef {
	t.Helper()
	var r invoiceRef
	if err := json.Unmarshal(raw, &r); err != nil {
		t.Fatal(err)
	}
	return r
}

// normalize decodes JSON so that two answers compare by content.
func normalize(t testing.TB, b []byte) any {
	t.Helper()
	var v any
	if err := json.Unmarshal(b, &v); err != nil {
		t.Fatal(err)
	}
	return v
}

